select s.*, c.name categoryName from drug_combo s left join category c on s.category_id = c.id
and s.name like concat('%',#{name},'%')
and s.status = #{status}
and s.category_id = #{categoryId}
order by s.create_time desc

select * from drug_combo

     and name like concat('%',#{name},'%') 
     and category_id = #{categoryId} 
     and status = #{status}

select count(id) from drug_combo

     and status = #{status} 
     and category_id = #{categoryId}
